package com.mestryer.pixelsky.core.crud; import java.util.*; import java.util.concurrent.*; import java.util.function.*; public class InMemoryCrudRepository<T,ID> implements CrudRepository<T,ID>{ private final Map<ID,T> data=new ConcurrentHashMap<>(); private final Function<T,ID> ids; public InMemoryCrudRepository(Function<T,ID> ids){this.ids=ids;} public T create(T e){ID id=ids.apply(e); if(id==null)throw new IllegalArgumentException("ID requerido"); if(data.putIfAbsent(id,e)!=null)throw new IllegalStateException("ID duplicado: "+id); return e;} public Optional<T> read(ID id){return Optional.ofNullable(data.get(id));} public List<T> readAll(){return new ArrayList<>(data.values());} public T update(ID id,T e){if(!data.containsKey(id))throw new IllegalArgumentException("No existe: "+id); data.put(id,e); return e;} public boolean delete(ID id){return data.remove(id)!=null;} }